import base64
import json
import os
from dataclasses import dataclass
from typing import Any, Dict, Optional, Union

import boto3
from botocore.exceptions import BotoCoreError, ClientError
from cryptography.hazmat.primitives.ciphers.aead import AESGCM


@dataclass
class EnvelopeCiphertext:
    kms_ciphertext_key: str
    nonce: str
    ciphertext: str
    aad: Optional[str] = None

    def to_json(self) -> str:
        return json.dumps(
            {
                "kms_ciphertext_key": self.kms_ciphertext_key,
                "nonce": self.nonce,
                "ciphertext": self.ciphertext,
                "aad": self.aad,
            },
            separators=(",", ":"),
        )

    @staticmethod
    def from_json(payload: Union[str, bytes, Dict[str, Any]]) -> "EnvelopeCiphertext":
        if isinstance(payload, dict):
            obj = payload
        else:
            if isinstance(payload, bytes):
                payload = payload.decode("utf-8")
            obj = json.loads(payload)
        return EnvelopeCiphertext(
            kms_ciphertext_key=obj["kms_ciphertext_key"],
            nonce=obj["nonce"],
            ciphertext=obj["ciphertext"],
            aad=obj.get("aad"),
        )


class EnvelopeEncryptionError(Exception):
    pass


class AwsKmsEnvelopeEncryptor:
    def __init__(self, key_id: str, region_name: Optional[str] = None):
        self.key_id = key_id
        self.kms = boto3.client("kms", region_name=region_name)

    @staticmethod
    def _b64encode(data: bytes) -> str:
        return base64.b64encode(data).decode("ascii")

    @staticmethod
    def _b64decode(data: str) -> bytes:
        return base64.b64decode(data.encode("ascii"))

    def encrypt(self, plaintext: Union[str, bytes], aad: Optional[Union[str, bytes]] = None) -> str:
        if isinstance(plaintext, str):
            plaintext_bytes = plaintext.encode("utf-8")
        else:
            plaintext_bytes = plaintext

        aad_bytes = None
        if aad is not None:
            aad_bytes = aad.encode("utf-8") if isinstance(aad, str) else aad

        try:
            data_key_response = self.kms.encrypt(KeyId=self.key_id, Plaintext=b"0" * 32)
            encrypted_data_key = data_key_response["CiphertextBlob"]
            plaintext_data_key = self.kms.decrypt(CiphertextBlob=encrypted_data_key)["Plaintext"]

            aesgcm = AESGCM(plaintext_data_key)
            nonce = os.urandom(12)
            ciphertext = aesgcm.encrypt(nonce, plaintext_bytes, aad_bytes)

            envelope = EnvelopeCiphertext(
                kms_ciphertext_key=self._b64encode(encrypted_data_key),
                nonce=self._b64encode(nonce),
                ciphertext=self._b64encode(ciphertext),
                aad=self._b64encode(aad_bytes) if aad_bytes is not None else None,
            )
            return envelope.to_json()
        except (BotoCoreError, ClientError, Exception) as exc:
            raise EnvelopeEncryptionError(f"Failed to encrypt data with AWS KMS envelope encryption: {exc}") from exc

    def decrypt(self, envelope_payload: Union[str, bytes, Dict[str, Any]]) -> bytes:
        envelope = EnvelopeCiphertext.from_json(envelope_payload)

        try:
            encrypted_data_key = self._b64decode(envelope.kms_ciphertext_key)
            nonce = self._b64decode(envelope.nonce)
            ciphertext = self._b64decode(envelope.ciphertext)
            aad_bytes = self._b64decode(envelope.aad) if envelope.aad is not None else None

            plaintext_data_key = self.kms.decrypt(CiphertextBlob=encrypted_data_key)["Plaintext"]
            aesgcm = AESGCM(plaintext_data_key)
            plaintext = aesgcm.decrypt(nonce, ciphertext, aad_bytes)
            return plaintext
        except (BotoCoreError, ClientError, Exception) as exc:
            raise EnvelopeEncryptionError(f"Failed to decrypt data with AWS KMS envelope encryption: {exc}") from exc


def encrypt_text(key_id: str, plaintext: str, aad: Optional[str] = None, region_name: Optional[str] = None) -> str:
    return AwsKmsEnvelopeEncryptor(key_id=key_id, region_name=region_name).encrypt(plaintext, aad=aad)


def decrypt_text(key_id: str, envelope_payload: Union[str, bytes, Dict[str, Any]], region_name: Optional[str] = None) -> str:
    plaintext = AwsKmsEnvelopeEncryptor(key_id=key_id, region_name=region_name).decrypt(envelope_payload)
    return plaintext.decode("utf-8")
